'use strict';
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
function battingResult(progress,easy=true){const error=Math.abs(progress-.78);return error<=(easy?.23:.13)?(error<=.065?'全壘打':'安打'):'揮空';}
function aimResult(progress,ax,ay,bx,by,easy=true){const timing=Math.abs(progress-.78);if(timing>(easy?.23:.13))return '揮空';if(Math.abs(ax-bx)>(easy?57:44)||Math.abs(ay-by)>(easy?43:34))return '瞄準偏了';return timing<=.065&&Math.hypot(ax-bx,ay-by)<=22?'全壘打':'安打';}

const pitcherProfiles={dad:{name:'雞爸爸',hand:'L',speed:150,sprite:2,types:['fastball','curve','sweeper','splitter','slider','sinker','changeup'],signature:'150 km/h · 各種球路'},mom:{name:'鼠媽媽',hand:'R',speed:130,sprite:3,types:['fastball','curve'],signature:'130 km/h · 快速球、曲球'},ama:{name:'兔阿嬤',hand:'R',speed:110,sprite:4,types:['fastball'],signature:'110 km/h · 直球'}};
const batterProfiles={dodo:{name:'鼠姊姊',hand:'R',sprite:0},dragon:{name:'龍弟弟',hand:'L',sprite:1}};
const pitchNames={fastball:'快速球',sweeper:'橫掃球',splitter:'指叉球',curve:'曲球',slider:'滑球',sinker:'伸卡球',changeup:'變速球'};
function pitchDuration(type,easy,speed=150){return ({fastball:1.9,sweeper:2.4,splitter:2.1,curve:2.7,slider:2.25,sinker:2.05,changeup:2.5}[type]||2.2)*(easy?1.35:1)*150/speed;}
function pitchPosition(progress,landing,type,hand='R'){const q=progress/.78,p=clamp(q,0,1),wave=Math.sin(Math.PI*p),start=hand==='L'?320:280,side=type==='sweeper'?65:type==='slider'?35:type==='sinker'?18:0,drop=type==='curve'?80:type==='splitter'?40:type==='changeup'?25:type==='sinker'?15:0;return {x:start+(landing.x-start)*q+(hand==='L'?-1:1)*side*wave,y:98+(landing.y-98)*q-drop*wave};}
const hoopLevels={easy:{label:'簡單',speed:1.4,half:.22},medium:{label:'中等',speed:2.4,half:.145},hard:{label:'困難',speed:3.8,half:.085}};
function hoopResult(direction,power,level='easy'){const half=hoopLevels[level].half;return Math.abs(direction-.5)<=half&&Math.abs(power-.5)<=half;}

const kingdomRegionCenters=[[155,315],[210,215],[285,110],[360,300],[535,270],[425,140]];
function kingdomRegionPolygons(){return kingdomRegionCenters.map((a,i)=>{let poly=[[0,0],[700,0],[700,500],[0,500]];for(let j=0;j<kingdomRegionCenters.length;j++){if(i===j)continue;const b=kingdomRegionCenters[j],nx=b[0]-a[0],ny=b[1]-a[1],limit=(b[0]**2+b[1]**2-a[0]**2-a[1]**2)/2,next=[];for(let k=0;k<poly.length;k++){const p=poly[k],q=poly[(k+1)%poly.length],dp=nx*p[0]+ny*p[1]-limit,dq=nx*q[0]+ny*q[1]-limit;if(dp<=0)next.push(p);if((dp<=0)!==(dq<=0)){const t=dp/(dp-dq);next.push([p[0]+(q[0]-p[0])*t,p[1]+(q[1]-p[1])*t]);}}poly=next;}return poly;});}
function newKingdom(){return {gold:12,food:18,troops:12,turn:1,actions:2,selected:0,ended:false,cities:[{name:'成都',owner:'you',def:0},{name:'漢中',owner:'neutral',def:4},{name:'長安',owner:'enemy',def:8},{name:'荊州',owner:'neutral',def:5},{name:'建業',owner:'enemy',def:7},{name:'許昌',owner:'enemy',def:10}]};}

