const bars=node('div','ag-hoop-bars'),horizontal=node('div','ag-bar ag-horizontal'),vertical=node('div','ag-bar ag-vertical');horizontal.setAttribute('role','img');vertical.setAttribute('role','img');const hzone=node('span','ag-valid-zone'),vzone=node('span','ag-valid-zone'),hdot=node('span','ag-meter-dot'),vdot=node('span','ag-meter-dot');horizontal.append(hzone,hdot);vertical.append(vzone,vdot);
const hwrap=node('div','ag-bar-wrap'),vwrap=node('div','ag-bar-wrap');hwrap.append(node('p','','① 左右方向'),horizontal,node('p','note','左 ←　有效區間　→ 右'));vwrap.append(node('p','','② 投籃力度'),vertical,node('p','note','上方強、下方弱'));const layout=node('div','ag-hoop-layout');root.insertBefore(layout,tip);layout.append(screen,vwrap,hwrap);screen.classList.add('ag-hoop-scene');hwrap.classList.add('ag-direction-panel');vwrap.classList.add('ag-power-panel');root.insertBefore(instruction,layout);
